import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:porto_prime/features/courier/presentation/widgets/courier_withdrawal_feedback.dart';

void main() {
  for (final width in [320.0, 390.0, 768.0]) {
    for (final status in ['PROCESSING', 'PAID', 'REJECTED']) {
      testWidgets('$status fits $width with large text', (tester) async {
        tester.view.physicalSize = Size(width, 760);
        tester.view.devicePixelRatio = 1;
        addTearDown(tester.view.resetPhysicalSize);
        addTearDown(tester.view.resetDevicePixelRatio);
        await tester.pumpWidget(MaterialApp(home: MediaQuery(
          data: MediaQueryData(size: Size(width, 760), textScaler: TextScaler.linear(2)),
          child: Scaffold(body: CourierWithdrawalFeedback(status: status, amount: 100)),
        )));
        await tester.pumpAndSettle();
        expect(tester.takeException(), isNull);
        expect(find.text('Pix processado!'), status == 'PAID' ? findsOneWidget : findsNothing);
      });
    }
  }
  testWidgets('same open surface switches from processing to server-confirmed paid', (tester) async {
    final status = ValueNotifier('PROCESSING');
    addTearDown(status.dispose);
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: ValueListenableBuilder<String>(
      valueListenable: status,
      builder: (_, value, child) => CourierWithdrawalFeedback(status: value, amount: 50),
    ))));
    expect(find.text('Pix processado!'), findsNothing);
    status.value = 'PAID';
    await tester.pumpAndSettle();
    expect(find.text('Pix processado!'), findsOneWidget);
    expect(find.text('Pagamento confirmado'), findsOneWidget);
  });
}

