import 'dart:async';
import 'package:flutter/material.dart';
import '../../../../core/state/app_state.dart';

/// Subscribes to wallet events; polls only while this surface is visible.
class CourierWalletLive extends StatefulWidget {
  const CourierWalletLive({super.key, required this.builder});
  final Widget Function(BuildContext, AppState) builder;
  @override
  State<CourierWalletLive> createState() => _CourierWalletLiveState();
}

class _CourierWalletLiveState extends State<CourierWalletLive>
    with WidgetsBindingObserver {
  Timer? _timer;
  bool _busy = false;
  late final Object? _account;
  final _state = AppState.instance;

  @override
  void initState() {
    super.initState();
    _account = _state.user?['id'];
    WidgetsBinding.instance.addObserver(this);
    _timer = Timer.periodic(const Duration(seconds: 5), (_) => _refresh());
    WidgetsBinding.instance.addPostFrameCallback((_) => _refresh());
  }

  Future<void> _refresh() async {
    if (!mounted || _busy || !_state.isCourier ||
        _state.user?['id'] != _account ||
        (WidgetsBinding.instance.lifecycleState != null &&
         WidgetsBinding.instance.lifecycleState != AppLifecycleState.resumed)) {
      return;
    }
    _busy = true;
    try { await _state.loadWallet(); } catch (_) {
      // Keep the last confirmed state; never infer payment on network failure.
    } finally { _busy = false; }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) { _refresh(); }
  }

  @override
  void dispose() {
    _timer?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => ListenableBuilder(
    listenable: _state,
    builder: (context, _) => _state.user?['id'] == _account && _state.isCourier
        ? widget.builder(context, _state) : const SizedBox.shrink(),
  );
}

