import { afterEach, expect, it, vi } from 'vitest';
vi.mock('../prisma/prisma.service.js', () => ({ PrismaService: class {} }));
vi.mock('../auth/auth.service.js', () => ({ AuthService: class {} }));
vi.mock('../realtime/realtime.gateway.js', () => ({ RealtimeGateway: class {} }));
import { AsaasPayoutService } from './asaas-payout.service.js';

afterEach(() => { vi.unstubAllEnvs(); vi.restoreAllMocks(); vi.useRealTimers(); });
function setup(pending: any[] = [], queued: any[] = []) {
  vi.stubEnv('ASAAS_PAYOUTS_ENABLED', 'true');
  const db: any = { asaasPayout: {
    findMany: vi.fn(async ({where}: any) => where.state === 'QUEUED' ? queued : pending),
    updateMany: vi.fn(async () => ({count: 1})),
  }};
  const service = new AsaasPayoutService(db, {} as any, {} as any);
  return {db, service};
}
it('reconciles existing transfers automatically without sending a new transfer', async () => {
  const {service,db} = setup([{withdrawalId:'w',transferId:'t'}]);
  const reconcile = vi.spyOn(service,'reconcile').mockResolvedValue({status:'PAID'});
  const send = vi.spyOn(service,'send');
  await service.tick();
  expect(reconcile).toHaveBeenCalledWith('t');
  expect(send).not.toHaveBeenCalled();
  expect(db.asaasPayout.findMany.mock.calls[0][0]).toMatchObject({
    where:{state:{in:['SENT','UNKNOWN','SENDING']},transferId:{not:null}},
    orderBy:[{updatedAt:'asc'},{withdrawalId:'asc'}],
  });
});
it('continues past a failed transfer and does not change its financial status', async () => {
  const {service,db}=setup([{withdrawalId:'w1',transferId:'t1'},{withdrawalId:'w2',transferId:'t2'}]);
  vi.spyOn((service as any).logger,'warn').mockImplementation(()=>{});
  const reconcile=vi.spyOn(service,'reconcile').mockRejectedValueOnce(new Error('timeout')).mockResolvedValueOnce({status:'PAID'});
  await service.tick();
  expect(reconcile).toHaveBeenCalledTimes(2);
  expect(db.asaasPayout.updateMany.mock.calls[0][0].data).toEqual({updatedAt:expect.any(Date)});
});
it('reconciles before attempting queued payouts and isolates queue errors',async()=>{
  const {service}=setup([{withdrawalId:'w',transferId:'t'}],[{withdrawalId:'q1'},{withdrawalId:'q2'}]);
  vi.spyOn((service as any).logger,'warn').mockImplementation(()=>{});
  const order:string[]=[];
  vi.spyOn(service,'reconcile').mockImplementation(async()=>{order.push('reconcile');return {};});
  vi.spyOn(service,'send').mockImplementation(async(id)=>{order.push(id);if(id==='q1')throw Error('failed');});
  await service.tick();expect(order).toEqual(['reconcile','q1','q2']);
});
it('does not run overlapping reconciliation cycles',async()=>{
  const {service}=setup([{withdrawalId:'w',transferId:'t'}]);
  let release!:()=>void;
  const gate=new Promise<void>(resolve=>{release=resolve;});
  const reconcile=vi.spyOn(service,'reconcile').mockImplementation(async()=>{await gate;return {};});
  const first=service.tick();await Promise.resolve();await service.tick();release();await first;
  expect(reconcile).toHaveBeenCalledTimes(1);
});
it('starts synchronization on boot and clears its timer on shutdown',async()=>{
  vi.useFakeTimers();vi.stubEnv('ASAAS_ENVIRONMENT','sandbox');vi.stubEnv('ASAAS_API_KEY','test');
  const {service}=setup();const tick=vi.spyOn(service,'tick').mockResolvedValue();
